create table public.access_requests (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, property_id uuid not null references public.properties_v2(id) on delete restrict, requested_email text not null, requester_user_id uuid references auth.users(id) on delete set null, status public.access_request_status not null default 'pending', requested_at timestamptz not null default now(), decided_at timestamptz, decided_by uuid references auth.users(id) on delete set null, rejection_reason text); alter table public.access_requests enable row level security;
